// Reuse PDF glyph outlines, including subset fonts without Unicode cmap tables.
export function createFontService(m){
 const pages=new Map(),uploaded=new Map(),shared=new Map();
 const clean=n=>String(n).replace(/^[A-Z]{6}\+/,'').replace(/[^a-z0-9]/gi,'').toLowerCase();
 function inventory(page){const fonts=new Map(),seen=new Set();function visit(resources,depth=0){if(depth>12||resources.isNull())return;resources.get('Font').forEach(f=>{const name=f.get('BaseFont').asName(),desc=f.get('DescendantFonts',0).isNull()?f:f.get('DescendantFonts',0),fd=desc.get('FontDescriptor');fonts.set(clean(name),{embedded:!fd.isNull()&&['FontFile','FontFile2','FontFile3'].some(k=>fd.get(k).isStream()),type:f.get('Subtype').asName()});});resources.get('XObject').forEach(x=>{const id=x.isIndirect()?x.asIndirect():x.pointer;if(seen.has(id))return;seen.add(id);if(x.get('Subtype').asName()==='Form')visit(x.get('Resources'),depth+1);});}visit(page.getObject().getInheritable('Resources'));return fonts;}
 function inspect(doc,sourceId,index){const id=sourceId+':'+index;if(pages.has(id))return pages.get(id);const p=doc.loadPage(index),records=[],byPointer=new Map(),info=inventory(p);
  function record(font){let r=byPointer.get(font.pointer);if(!r){const name=font.getName(),details=info.get(clean(name)),standard=/^(Helvetica|Times(Roman|-Roman|-Bold|-Italic|-BoldItalic)?|Courier|Symbol|ZapfDingbats)(-|$)/i.test(name);r={font:new m.Font(font.pointer),key:'font-'+records.length,name,chars:shared.get(sourceId+':'+font.pointer)||new Map(),embedded:details?.embedded===true,standard,available:details?.type!=='Type3'&&(details?.embedded===true||standard)};shared.set(sourceId+':'+font.pointer,r.chars);records.push(r);byPointer.set(font.pointer,r);}return r;}
  const visitor=new m.Device({fillText(text){walk(text);},strokeText(text){walk(text);},ignoreText(text){walk(text);}});
  function walk(text){text.walk({showGlyph(font,trm,gid,unicode){const r=record(font);if(gid>0&&unicode>=0&&unicode<=0x10ffff)r.chars.set(String.fromCodePoint(unicode),gid);}});}
  p.run(visitor,m.Matrix.identity);visitor.close();visitor.destroy();let line=null,dir=[1,0];const lines=[],images=[],st=p.toStructuredText('preserve-images');
  function flush(){if(line?.text.trim())lines.push(line);line=null;}
  st.walk({beginLine(b,w,d){flush();dir=d;},onChar(c,origin,font,size,quad,color){const r=record(font),hex='#'+[0,1,2].map(i=>Math.round((color[i]??color[0]??0)*255).toString(16).padStart(2,'0')).join('');if(line&&(line.fontKey!==r.key||Math.abs(line.size-size)>.02||line.color!==hex))flush();const xs=[quad[0],quad[2],quad[4],quad[6]],ys=[quad[1],quad[3],quad[5],quad[7]],b=[Math.min(...xs),Math.min(...ys),Math.max(...xs),Math.max(...ys)];if(!line)line={text:'',rect:b,origin,size,color:hex,direction:dir,font:r.name,fontKey:r.key,fontAvailable:r.available,fontEmbedded:r.embedded,fontStandard:r.standard};else line.rect=[Math.min(line.rect[0],b[0]),Math.min(line.rect[1],b[1]),Math.max(line.rect[2],b[2]),Math.max(line.rect[3],b[3])];line.text+=c;},endLine:flush,onImageBlock(b){images.push({rect:b});}});st.destroy();p.destroy();const result={lines,images,records};pages.set(id,result);return result;
 }
 function unicodeHex(char){return Array.from({length:char.length},(_,i)=>char.charCodeAt(i).toString(16).padStart(4,'0')).join('');}
 function render(doc,ref,o,preview=true){let record;
  if(ref.upload){if(uploaded.get(ref.upload.id)?.data!==ref.upload.data){uploaded.get(ref.upload.id)?.font.destroy();const raw=Uint8Array.from(atob(ref.upload.data),c=>c.charCodeAt(0));uploaded.set(ref.upload.id,{font:new m.Font(ref.upload.name,raw),name:ref.upload.name,data:ref.upload.data,chars:new Map(),available:true,embedded:true});}record=uploaded.get(ref.upload.id);}
  else record=inspect(doc,ref.sourceId,ref.index).records.find(r=>r.key===ref.key);
  if(!record?.available)return {missing:[],reason:'PDF’de kullanılabilir özgün font gömülü değil. Font dosyasını yükleyin veya Noto Sans’ı seçin.'};
  if(!ref.upload&&[...o.text.replaceAll('\n','').replaceAll('\t',' ')].some(c=>!record.font.encodeCharacter(c)&&!record.chars.has(c))){for(let i=0;i<doc.countPages();i++){inspect(doc,ref.sourceId,i);if([...o.text.replaceAll('\n','').replaceAll('\t',' ')].every(c=>record.font.encodeCharacter(c)||record.chars.has(c)))break;}}
  const missing=new Set(),mapping=new Map(),encoded=[],size=o.size||16;let widest=0;
  for(const line of o.text.replaceAll('\t','    ').split('\n')){let width=0;const glyphs=[];for(const c of line){const gid=record.font.encodeCharacter(c)||record.chars.get(c)||0;if(!gid){missing.add(c);continue;}glyphs.push(gid);mapping.set(gid,c);width+=record.font.advanceGlyph(gid)*size;}widest=Math.max(widest,width);encoded.push({glyphs,width});}
  if(missing.size)return {missing:[...missing],reason:'Özgün fontta bu karakterler yok: '+[...missing].join(' ')};
  const width=Math.max(1,o.w,widest+2),height=Math.max(1,o.h,encoded.length*size*1.35),out=new m.PDFDocument();
  try{const font=out.addFont(record.font),pairs=[...mapping].map(([g,c])=>`<${g.toString(16).padStart(4,'0')}> <${unicodeHex(c)}>`),blocks=[];for(let i=0;i<pairs.length;i+=90)blocks.push(`${Math.min(90,pairs.length-i)} beginbfchar\n${pairs.slice(i,i+90).join('\n')}\nendbfchar`);
   const cmap=`/CIDInit /ProcSet findresource begin 12 dict begin begincmap /CIDSystemInfo << /Registry (Adobe) /Ordering (UCS) /Supplement 0 >> def /CMapName /ekoPDFFont def /CMapType 2 def 1 begincodespacerange <0000> <FFFF> endcodespacerange ${blocks.join('\n')} endcmap CMapName currentdict /CMap defineresource pop end end`;
   font.put('ToUnicode',out.addStream(cmap,{}));const n=parseInt((o.color||'#202620').slice(1),16),color=[(n>>16&255)/255,(n>>8&255)/255,(n&255)/255];
   let contents=`q /GS gs ${color.join(' ')} rg\n`;encoded.forEach((line,i)=>{const x=o.align==='center'?(o.w-line.width)/2:o.align==='right'?o.w-line.width:0;contents+=`BT /F0 ${size} Tf 1 0 0 1 ${x} ${height-size-i*size*1.35} Tm <${line.glyphs.map(g=>g.toString(16).padStart(4,'0')).join('')}> Tj ET\n`;});contents+='Q';out.insertPage(0,out.addPage([0,0,width,height],0,{Font:{F0:font},ExtGState:{GS:{Type:'ExtGState',ca:o.opacity??1,CA:o.opacity??1}}},contents));
   const b=out.saveToBuffer('garbage=4,compress'),result={bytes:b.asUint8Array().slice(),width,height,missing:[],name:record.name};b.destroy();if(preview){const p=out.loadPage(0),pix=p.toPixmap(m.Matrix.scale(2,2),m.ColorSpace.DeviceRGB,true);result.png=pix.asPNG().slice();pix.destroy();p.destroy();}return result;
  }finally{out.destroy();}
 }
 return {inspect,render,clear(sourceId){for(const key of shared.keys())if(key.startsWith(sourceId+':'))shared.delete(key);for(const [key,p]of pages)if(key.startsWith(sourceId+':')){p.records.forEach(r=>r.font.destroy());pages.delete(key);}}};
}
